using System;using System.IO;using System.Collections.Generic;
namespace VintageCollector.Funds {public static class LedgerBackup {public static LedgerSnapshot ValidateArchiveFiles(IDictionary<string,byte[]> files){if(files==null)throw new ArgumentNullException("files");foreach(string key in files.Keys)if(key!="fund.state.json"&&key!="fund.backup.json"&&key!="fund.ack.json")throw new InvalidDataException("Unexpected fund archive member");if(!files.ContainsKey("fund.state.json")||!files.ContainsKey("fund.ack.json"))throw new InvalidDataException("Missing acknowledged fund files");var state=LedgerJsonCodec.Decode<LedgerData>(files["fund.state.json"]);var ack=LedgerJsonCodec.Decode<LedgerData>(files["fund.ack.json"]);LedgerRules.Validate(state);LedgerRules.Validate(ack);if(state.contentHash!=ack.contentHash)throw new InvalidDataException("Archive acknowledgement mismatch");if(files.ContainsKey("fund.backup.json")){var backup=LedgerJsonCodec.Decode<LedgerData>(files["fund.backup.json"]);LedgerRules.Validate(backup);LedgerRules.Link(state,backup);}else if(state.revision>1)throw new InvalidDataException("Missing backup lineage");return new LedgerSnapshot(state);}}}
